head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.selfID = ""; // ID를 opener가 넘기는 값을 받는 변수형태로 사용하기 위함.
scwin.strTeam = js_team;
scwin.strDepCd = js_dep_cd.substring(0, 2);

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.hideDebugCtrls();
        scwin.resizeToWin();
        await scwin.setCode();
        scwin.selfID = frame.FrameID; // ID 할당.
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30002.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name cmb_Adm_Itm_onselchange
 * @description cmb_Adm_Itm onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_Adm_Itm_onselchange = async function() {
    try {
        await scwin.listManageItem();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30002.cmb_Adm_Itm_onselchange" });
    }
};

/**
 * @method
 * @name grd_Adm_Itm_OnDblClick
 * @description grd_Adm_Itm 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Adm_Itm_OnDblClick = async function(row, colid) {
    try {
        await scwin.setAdm_Itm(grd_Adm_Itm, row, colid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30002.grd_Adm_Itm_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30002.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name dts_Adm_Itm_Cmb_OnLoadCompleted
 * @description dts_Adm_Itm_Cmb 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Adm_Itm_Cmb_OnLoadCompleted = function(rowcount) {
    // alert('dts_Adm_Itm_Cmb.OnLoadCompleted('+rowcount+')');

};

/**
 * @method
 * @name dts_Adm_Itm_Cmb_OnLoadError
 * @description dts_Adm_Itm_Cmb 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Adm_Itm_Cmb_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Adm_Itm_Cmb);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30002.dts_Adm_Itm_Cmb_OnLoadError" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
// 카테고리(선택박스)

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    let flag = (js_market === "1") ? "0" : "9";
    url += "&UP_SCHDL_ADM_ITM_TP_CD=" + flag;
    url += "&MKT_ID=" + js_market;
    url += "&TEAM_ID=" + js_team;
    const sbmOptions = {
        id : "sbm_dts_Adm_Itm_Cmb",
        action : "/DisclosureSchedule.do",
        ref : "",
        target : "dts_Adm_Itm_Cmb=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // alert(url);
    if (js_market === "2" || js_market === "9" || js_market === "6") {
        // 코넥스 추가 20130522 LDJ
        cmb_Adm_Itm.setDisabled(false);
    }
    // cmb_Adm_Itm.Enable2 = true;
    cmb_Adm_Itm.setValue("9");
    // alert(getObjectValue(cmb_Adm_Itm));

};

/**
 * @method
 * @name listManageItem
 * @description 카테고리에 따른 목록
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listManageItem = async function() {
    // 증권상품팀 구분을 위해 20210528
    let flag = "0";
    if (js_market === "1") {
        if (scwin.strDepCd === "2B") {
            flag = "6";
            scwin.strTeam = "16";
        }
        if (js_dep_cd === "11D0") {
            flag = "3";
            scwin.strTeam = "11D0";
        }
    } else {
        flag = cmb_Adm_Itm.getValue();
    }

    // var flag = (js_market == "1") ? "0":  getObjectValue(cmb_Adm_Itm);
    url += "&UP_SCHDL_ADM_ITM_TP_CD=" + flag;
    url += "&TEAM_ID=" + scwin.strTeam;
    url += "&MKT_ID=" + js_market;
    url += "&SCREN_ID=" + 'ULDSTF30002.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Adm_Itm_List",
        action : "/DisclosureSchedule.do",
        ref : "",
        target : "dts_Adm_Itm_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name resizeToWin
 * @description resize To Win 처리
 * @returns {void}
 * @hidden N
 */
scwin.resizeToWin = function() {
    frame.Width = 280;
    frame.Height = 420;
    $c.stf.MoveCenterOfParent();
};

/**
 * @method
 * @name hideGridCol
 * @description hide Grid Col 처리
 * @param {String} GridID GridID
 * @returns {void}
 * @hidden N
 */
scwin.hideGridCol = function(GridID) {
    const ColCnt = GridID.getTotalCol();
    for (let i = 0; i < ColCnt; i++) {
        const ColID = GridID.GetColumnID(i);
        const HeaderNm = GridID.GetHdrDispName(-3, ColID);
        if (scwin.isEngChar(HeaderNm)) {
            // 영문 컬럼이면 숨겨라.
            GridID.setColumnProp(ColID, "Show", false);
        }
    }
};

/**
 * @method
 * @name hideDebugCtrls
 * @description hide Debug Ctrls 처리
 * @returns {void}
 * @hidden N
 */
scwin.hideDebugCtrls = function() {
    scwin.hideGridCol(grd_Adm_Itm);
};

/**
 * @method
 * @name isEngChar
 * @description is Eng Char 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.isEngChar = function(str) {
    const re = /[^-a-z_A-Z]/; // 영문자가 아닌 게 있는 걸 찾아라.
    return !re.test(str);
};

/**
 * @method
 * @name setAdm_Itm
 * @description set Adm Itm 처리
 * @param {String} GridID GridID
 * @param {Number} row 행 인덱스
 * @param {String} ColID ColID
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setAdm_Itm = async function(GridID, row, ColID) {
    if (scwin.selfID === "ONLYFORGRID") {
        await scwin.setAdm_Itm_For_Grid(GridID, row, ColID);
    } else {
        await scwin.setAdm_Itm_Default(GridID, row, ColID);
    }
};

/**
 * @method
 * @name setAdm_Itm_Default
 * @description set Adm Itm Default 처리
 * @param {String} GridID GridID
 * @param {Number} row 행 인덱스
 * @param {String} ColID ColID
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setAdm_Itm_Default = async function(GridID, row, ColID) {
    let objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..

    let parentWin = $c.frame.path("../");
    parentWin.txb_SCHDL_ADM_ITM_TP_CD.setValue(objDataID.getCellData(row, "SCHDL_ADM_ITM_TP_CD"));
    parentWin.txb_SCHDL_ADM_ITM_TP_NM.setValue(objDataID.getCellData(row, "CD_NM"));
    // setObjectValue(parentWin.txb_DISCLS_SCHDL_ADM_CONTN, objDataID.NameString(row, "CD_NM"));

    await $c.win.closePopup();
};

/**
 * @method
 * @name setAdm_Itm_For_Grid
 * @description set Adm Itm For Grid 처리
 * @param {String} GridID GridID
 * @param {Number} row 행 인덱스
 * @param {String} ColID ColID
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setAdm_Itm_For_Grid = async function(GridID, row, ColID) {
    let objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..

    let parentWin = $c.frame.path("../");
    // var parentDataID = opener.document.all();
    parentWin.dts_Grid.setCellData(parentWin.dts_Grid.getFocusedRowIndex(), "SCHDL_ADM_ITM_TP_CD", objDataID.getCellData(row, "SCHDL_ADM_ITM_TP_CD"));
    parentWin.dts_Grid.setCellData(parentWin.dts_Grid.getFocusedRowIndex(), "SCHDL_ADM_ITM_TP_NM", objDataID.getCellData(row, "CD_NM"));
    // parentWin.dts_Grid.NameValue(parentWin.dts_Grid.RowPosition, "DISCLS_SCHDL_ADM_CONTN") = objDataID.NameString(row, "CD_NM");

    await $c.win.closePopup();
};
